#!/usr/bin/env python3
"""
Round 144b (culprits), 2 October 2026. Needs round 143b.

Combine the ticked layers: share of each layer crossed, worldwide and in view.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 144b (2 October)\n\nNeeds round 143b. No tiles patch. No app.js?v= bump.\n\n- Combine the ticked layers: how much of each layer is crossed (asked 2\n  October), in the combine box under its message (#combo-stats). For each\n  layer taking part: the share of it crossed by any other group, or by one\n  group picked in the menu (#combo-by), worldwide and in the part of the map\n  in view (comboViewCells from map.getBounds, wrapping round 180 degrees).\n  Places count one each; areas and pictures count the ground they cover\n  (cover x cos latitude). "Crossed" is the outline\'s own test: a layer of\n  that group present in the square (within about 50 km; in "highest values",\n  in its own top fifth). comboBuild keeps each layer\'s squares sparsely\n  (COMBO.stats); comboShares adds them up; the view share is redone on every\n  map move. Worldwide is all the map has read of a layer, so tiled layers\n  grow as the reader looks round (the box says so).\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round144b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 143b" not in h.read_text(encoding="utf-8"):
        sys.exit("round144b: round 143b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round144b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round144b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round144b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ""

if __name__ == "__main__":
    main()
